function tpc_publication_figures(codeDir,section,displayMode)
% Rebuild only stale figures from saved evidence; never retrain or query a
% fallback controller. Dense displays are sampled, numerical metrics are not.
if nargin<2,section='all';end
if nargin<3,displayMode='none';end
% Keep seven evidence categories. The three overlapping diagnostics below
% are no longer generated by normal stages, including section='all'.
essentialStems={'01_identification','03_empc_control_law','05_neural_fit',...
 '07_closed_loop','08_event_enlargements','09_steady_ripple','10_trajectory_teacher_comparison'};
root=tpc_project_root();
cfg=tpc_load_case(codeDir);switching=isfield(cfg,'mapping');
configName='case_config.json';if switching,configName='switch_config.json';end
cfg=tpc_load_case(codeDir);cfg.codeDir=codeDir;
voltageSymbol='V_o';if strcmp(cfg.id,'SISO_VS_VB'),voltageSymbol='V_b';end
voltageLabel=[voltageSymbol ' / V'];
outDir=fullfile(codeDir,'results','figures');if ~isfolder(outDir),mkdir(outDir);end
desktop=usejava('desktop')&&strcmp(displayMode,'all');palette=[.00 .32 .56;.85 .33 .10;.00 .55 .40;.55 .25 .65];
manifest=struct('name',{},'files',{},'evidence',{});
if switching
 if strcmp(section,'all')
  C=tpc_read_cases(fullfile(root,'config','target_cases.json'));
  for mode=unique({cfg.mapping.mode})
   j=find(strcmp({C.id},mode{1}),1);
   tpc_publication_figures(C(j).codeDir,'empc',displayMode);
   tpc_publication_figures(C(j).codeDir,'network',displayMode);
  end
 end
else
 if wanted('identify')
  modelsFile=fullfile(codeDir,'models','identified_model.mat');rawDir=fullfile(codeDir,'data','prbs');
  raw=dir(fullfile(rawDir,'raw_R*.mat'));deps=[{modelsFile},arrayfun(@(q)fullfile(rawDir,q.name),raw,'UniformOutput',false)'];
  if ready('01_identification',deps)
   S=load(modelsFile,'models');n=numel(S.models);f=newFigure('01 Identification',1250,1000);tiledlayout(4,n,'TileSpacing','compact');
   for j=1:n
    M=S.models{j};R=load(fullfile(rawDir,sprintf('raw_R%g.mat',M.Rload)),'t','a');
    ix=find(R.t>=-1e-10 & abs(R.t/M.Ts-round(R.t/M.Ts))<1e-5);v=R.a(ix,:);tt=R.t(ix(2:end))*1e3;
    pred=(M.A*v(1:end-1,1:2)'+M.B*v(1:end-1,4:3+size(M.B,2))'+M.f)';truth=v(2:end,1:2);err=pred-truth;
    for row=1:4
     nexttile((row-1)*n+j);hold on;channel=1+mod(row-1,2);
     if row<=2
      plot(tt,truth(:,channel),'Color',palette(1,:));plot(tt,pred(:,channel),'--','Color',palette(2,:));
      if row==1,title(sprintf('R = %g Ohm; training / held-out',M.Rload));legend('Electrical measurement','One-step prediction','Location','best');end
     else
      plot(tt,err(:,channel),'Color',palette(channel,:));yline(0,'k:');
      title(sprintf('Held-out RMSE = %.3g %s',sqrt(mean(err(M.trainingSamples+1:end,channel).^2)),unit(channel)));
     end
     xline(tt(min(M.trainingSamples,numel(tt))),'k:');xlabel('Time / ms');
     labels={'i_L(k+1) / A',[voltageSymbol '(k+1) / V'],'Current error / A','Voltage error / V'};ylabel(labels{row});decorate();
    end
   end
   finish(f,'01_identification',deps);
  end
 end
 if wanted('empc')
  indexFile=fullfile(codeDir,'models','EMPC_48_72_120.mat');S=load(indexFile,'teachers');
  deps={indexFile};for j=1:numel(S.teachers),T=S.teachers{j};deps{end+1}=fullfile(codeDir,'generated',['empc_' erase(T.functionName,'Bstep_') '.mat']);end
  geometry=cell(1,numel(S.teachers));
  if ready('02_empc_partition',deps)
   n=numel(S.teachers);f=newFigure('02 Exact EMPC critical regions',1250,820);tiledlayout(2,n,'TileSpacing','compact');
   for j=1:n
    E=load(deps{j+1},'e','teacher');geometry{j}=criticalGeometry(E);G=geometry{j};V=G.xy;F=G.faces;
    for row=1:2
     nexttile((row-1)*n+j);patch('Vertices',V,'Faces',F,'FaceVertexCData',(1:size(F,1))','FaceColor','flat','EdgeColor',[.18 .18 .18],'LineWidth',.25);
     colormap(gca,parula(256));xlabel('i_L / A');ylabel(voltageLabel);decorate();
     if row==1,title(sprintf('R = %g Ohm; %d exact regions',E.teacher.Rload,G.regionCount));axis tight;
     else
      M=load(fullfile(codeDir,'models','identified_model.mat'),'models');q=find(cellfun(@(m)m.Rload==E.teacher.Rload,M.models),1);anchor=M.models{q}.steadyAnchor.x;
      xlim([max(0,anchor(1)-2),min(cfg.currentMax,anchor(1)+2)]);ylim(cfg.Vref+[-.5 .5]);title('Operating-point enlargement');
     end
    end
   end
   finish(f,'02_empc_partition',deps);
  end
  if ready('03_empc_control_law',deps)
   n=numel(S.teachers);f=newFigure('03 Exact piecewise-affine EMPC laws',1250,440*cfg.nu);tiledlayout(cfg.nu,n,'TileSpacing','compact');
   for j=1:n
    if isempty(geometry{j}),E=load(deps{j+1},'e','teacher');geometry{j}=criticalGeometry(E);end
   end
   for head=1:cfg.nu
    for j=1:n
     nexttile((head-1)*n+j);G=geometry{j};V=[G.xy G.u(:,head)];
     patch('Vertices',V,'Faces',G.faces,'FaceVertexCData',G.u(:,head),'FaceColor','interp','EdgeColor',[.25 .25 .25],'LineWidth',.12);
     xlabel('i_L / A');ylabel(voltageLabel);zlabel(sprintf('d_%d',head));title(sprintf('R = %g Ohm; exact affine facets',S.teachers{j}.Rload));view(-40,25);colorbar;
     lower=0;if isfield(cfg,'dutyMin')&&~isempty(cfg.dutyMin),lower=cfg.dutyMin(head);end;caxis([lower cfg.dutyMax(head)]);decorate();
    end
   end
   finish(f,'03_empc_control_law',deps);
  end
 end
 if wanted('samples')
  file=fullfile(codeDir,'data','changeR1.mat');
  if ready('04_sample_distribution',{file})
   S=load(file,'changeR1');D=S.changeR1;rows=thin((1:size(D,1))',10000);family=loadFamily(D);
   f=newFigure('04 Training-data coverage',1250,820);tiledlayout(2,2,'TileSpacing','compact');
   nexttile;scatter(D(rows,1),D(rows,2),6,family(rows),'filled');xlabel('i_L / A');ylabel(voltageLabel);title(sprintf('State coverage; %d samples (display subset)',size(D,1)));cb=colorbar;cb.Ticks=1:numel(cfg.Rloads);cb.TickLabels=compose('%g Ohm',cfg.Rloads);decorate();
   nexttile;scatter3(D(rows,1),D(rows,2),D(rows,3),6,family(rows),'filled');xlabel('i_L / A');ylabel(voltageLabel);zlabel('Measured-current feature / A');view(-40,25);title('Four-input dataset; fixed reference');decorate();
   nexttile;hold on;for h=1:cfg.nu,histogram(D(:,4+h),60,'Normalization','probability','DisplayStyle','stairs','LineWidth',1.2,'DisplayName',sprintf('d_%d',h));end;xlabel('EMPC duty label');ylabel('Probability');legend('show');title('All retained labels');decorate();
   nexttile;counts=accumarray(family,1,[numel(cfg.Rloads) 1]);bar(counts,'FaceColor',palette(1,:));xticks(1:numel(counts));xticklabels(compose('%g Ohm',cfg.Rloads));ylabel('Retained samples');title('Load-family coverage (augmentation included)');decorate();
   finish(f,'04_sample_distribution',{file});
  end
 end
 if wanted('network')
  file=fullfile(codeDir,'models','net_48_72_120.mat');holdFile=fullfile(codeDir,'data','offgrid_holdout.mat');
  deps={file,holdFile};
  if ready('05_neural_fit',{deps{:}})
   N=load(file,'history','training','holdoutPrediction');H=load(holdFile,'holdout');truth=H.holdout(:,5:end);pred=N.holdoutPrediction';
   f=newFigure('05 Neural-network convergence and held-out fit',1250,850);tiledlayout(2,2,'TileSpacing','compact');
   nexttile;semilogy(N.history(:,1),N.history(:,2),'Color',palette(1,:),'LineWidth',1.2);hold on;semilogy(N.history(:,1),N.history(:,3),'--','Color',palette(2,:),'LineWidth',1.2);yline(N.training.goal,'k--','Goal');xline(N.training.bestUpdate,'k:');xlabel('Gradient updates');ylabel('MSE (sum across outputs)');legend('Training','Validation','Goal','Selected update','Location','best');title('Actual history; goal is not assumed reached');decorate();
   nexttile;hold on;rows=thin((1:size(truth,1))',5000);for h=1:cfg.nu,scatter(truth(rows,h),pred(rows,h),7,palette(h,:),'filled','DisplayName',sprintf('d_%d',h));end;plot([0 1],[0 1],'k--','DisplayName','Identity');xlabel('Independent EMPC label');ylabel('Raw NN prediction');legend('show','Location','best');axis equal;title('Independent off-grid hold-out');decorate();
   nexttile;hold on;for h=1:cfg.nu,histogram(pred(:,h)-truth(:,h),80,'Normalization','probability','DisplayStyle','stairs','LineWidth',1.2,'DisplayName',sprintf('d_%d',h));end;xlabel('Raw NN - EMPC duty');ylabel('Probability');legend('show');title('All off-grid errors; no duty clipping');decorate();
   nexttile;hold on;for h=1:cfg.nu,e=sort(abs(pred(:,h)-truth(:,h)));plot(e,(1:numel(e))/numel(e),'LineWidth',1.2,'DisplayName',sprintf('d_%d: RMSE %.3g; max %.3g',h,sqrt(mean(e.^2)),max(e)));end;xlabel('Absolute duty error');ylabel('Empirical cumulative probability');ylim([0 1]);legend('show','Location','best');title('Tail errors remain visible');decorate();
   finish(f,'05_neural_fit',deps);
  end
  if ready('06_neural_spatial_error',deps)
   N=load(file,'holdoutPrediction');H=load(holdFile,'holdout');D=H.holdout;pred=N.holdoutPrediction';rows=thin((1:size(D,1))',10000);
   f=newFigure('06 Neural approximation error over state space',1250,400*cfg.nu);tiledlayout(cfg.nu,2,'TileSpacing','compact');
   for h=1:cfg.nu
    e=pred(:,h)-D(:,4+h);nexttile;scatter(D(rows,1),D(rows,2),7,abs(e(rows)),'filled');colorbar;xlabel('i_L / A');ylabel(voltageLabel);title(sprintf('d_%d: absolute error, independent off-grid states',h));decorate();
    nexttile;scatter3(D(rows,1),D(rows,2),pred(rows,h),6,abs(e(rows)),'filled');colorbar;xlabel('i_L / A');ylabel(voltageLabel);zlabel(sprintf('Raw NN d_%d',h));view(-40,25);title('NN distribution; colour = absolute duty error');decorate();
   end
   finish(f,'06_neural_spatial_error',deps);
  end
 end
end
if wanted('closed')||switching
 file=fullfile(codeDir,'results','switching_dynamic.mat');
 if isfile(file)
  if ready('07_closed_loop',{file})
   S=load(file,'t','a','cfg');t=S.t;a=S.a;rows=envelopeRows(a,1500);
   f=newFigure('07 Electrical closed-loop overview',1250,950);tiledlayout(4,1,'TileSpacing','compact');
   nexttile;plot(t(rows)*1e3,a(rows,2));hold on;yline(cfg.Vref,'--','Reference');ylabel('Controlled voltage / V');title([cfg.id ': actual switching circuit; initialization excluded'],'Interpreter','none');decorate();
   nexttile;plot(t(rows)*1e3,a(rows,1));ylabel('i_L / A');decorate();
   nexttile;plot(t(rows)*1e3,a(rows,3));ylabel('i_o / A');decorate();
   nexttile;plot(t(rows)*1e3,a(rows,4:end));ylabel('Applied duty');xlabel('Time since feedback enable / ms');legend(compose('Command %d',1:size(a,2)-3),'Location','best');decorate();
   finish(f,'07_closed_loop',{file});
  end
  if ready('08_event_enlargements',{file})
   S=load(file,'t','a','report');t=S.t;a=S.a;n=numel(cfg.events);f=newFigure('08 Load or mode-transition enlargements',1250,900);tiledlayout(3,n,'TileSpacing','compact');
   for j=1:n
    te=cfg.events(j);w=t>=te-.0002&t<=te+.001;xx=(t(w)-te)*1e6;cycle=floor((t(w)-te)/cfg.Ts+1e-6);[~,~,g]=unique(cycle);avgT=accumarray(g,xx,[],@mean);avgV=accumarray(g,a(w,2),[],@mean);
    count=accumarray(g,1);sampleTs=median(diff(t(1:min(1000,numel(t)))));complete=count>=.99*cfg.Ts/sampleTs;avgT=avgT(complete);avgV=avgV(complete);
    nexttile(j);plot(xx,a(w,2),'Color',[.65 .75 .85]);hold on;plot(avgT,avgV,'Color',palette(1,:),'LineWidth',1.4);xline(0,'k:');yline(cfg.Vref,'k--');legend('Electrical samples','PWM-cycle mean','Location','best');ylabel('Voltage / V');title(sprintf('Event %.3g ms: %.3g V departure; %.3g us recovery',te*1e3,S.report.events(j).peakDepartureV,S.report.events(j).settlingToPostUs));decorate();
    nexttile(n+j);plot(xx,a(w,1));xline(0,'k:');ylabel('i_L / A');decorate();
    nexttile(2*n+j);plot(xx,a(w,4:end));xline(0,'k:');ylabel('Applied duty');xlabel('Time from event / us');decorate();
   end
   finish(f,'08_event_enlargements',{file});
  end
  if ready('09_steady_ripple',{file})
   S=load(file,'t','a','report');n=numel(S.report.plateaus);f=newFigure('09 Settled PWM ripple at each plateau',1350,820);tiledlayout(3,n,'TileSpacing','compact');
   for j=1:n
    p=S.report.plateaus(j);stop=p.timeWindow(2)-2*cfg.Ts;w=S.t>=stop-5*cfg.Ts & S.t<stop;xx=(S.t(w)-(stop-5*cfg.Ts))*1e6;
    nexttile(j);plot(xx,S.a(w,2));ylabel('Voltage / V');title(sprintf('Plateau %d; mean %.5g V',j,p.meanVoltage));decorate();
    nexttile(n+j);plot(xx,S.a(w,1));ylabel('i_L / A');decorate();
    nexttile(2*n+j);plot(xx,S.a(w,4:end));ylabel('Applied duty');xlabel('Local time / us');decorate();
   end
   finish(f,'09_steady_ripple',{file});
  end
 end
 trajectory=fullfile(codeDir,'results','NN_native_trajectory.mat');
 if ~switching&&isfile(trajectory)&&ready('10_trajectory_teacher_comparison',{trajectory})
  S=load(trajectory,'target','prediction','log','feasible');tt=(S.log(:,1)-S.log(1,1))*1e3;f=newFigure('10 EMPC and NN on actual electrical trajectory',1250,380*cfg.nu);tiledlayout(cfg.nu,2,'TileSpacing','compact');
  for h=1:cfg.nu
   nexttile;plot(tt,S.target(:,h),'Color',palette(1,:));hold on;plot(tt,S.prediction(:,h),'--','Color',palette(2,:));xlabel('Feedback time / ms');ylabel(sprintf('d_%d',h));legend('Exact EMPC query','Raw NN');title('Same measured states; not separate closed-loop trajectories');decorate();
   nexttile;plot(tt,S.prediction(:,h)-S.target(:,h));yline(0,'k:');xlabel('Feedback time / ms');ylabel('NN - EMPC duty');title(sprintf('Feasible teacher queries: %d / %d',sum(S.feasible),numel(S.feasible)));decorate();
  end
  finish(f,'10_trajectory_teacher_comparison',{trajectory});
 end
end
manifestFile=fullfile(outDir,'figure_manifest.json');
if isfile(manifestFile)
 previous=jsondecode(fileread(manifestFile));
 if ~isempty(previous),manifest=[previous(:);manifest(:)];[~,last]=unique({manifest.name},'last');manifest=manifest(sort(last));end
end
fid=fopen(manifestFile,'w');fprintf(fid,'%s',jsonencode(manifest,PrettyPrint=true));fclose(fid);
fprintf('PUBLICATION_FIGURES %s %s; saved .fig / 450dpi .png / print-ready .pdf\n',cfg.id,section);

 function yes=wanted(name),yes=strcmp(section,'all')||strcmp(section,name);end
 function family=loadFamily(D),[~,family]=min(abs(D(:,2)./max(D(:,3),1e-9)-cfg.Rloads(:)'),[],2);end
 function yes=ready(stem,deps)
  if ~ismember(stem,essentialStems),yes=false;return;end
  if ~all(cellfun(@isfile,deps)),fprintf('PLOT_PENDING %s %s: prerequisite artifact unavailable\n',cfg.id,stem);yes=false;return;end
  dest=fullfile(outDir,[stem '.fig']);d=dir(dest);latest=dir([mfilename('fullpath') '.m']);stamp=latest.datenum;
  exporter=dir(which('tpc_export_figure_pdf'));stamp=max(stamp,exporter.datenum);
  for z=1:numel(deps),q=dir(deps{z});stamp=max(stamp,q.datenum);end
  manifest(end+1)=struct('name',stem,'files',{{[stem '.fig'],[stem '.png'],[stem '.pdf']}},'evidence',{deps});
  yes=isempty(d)||d.datenum<stamp;
  if yes,fprintf('PLOT_BUILD %s %s\n',cfg.id,stem);end
  if ~yes && desktop
   tag=[cfg.id '_' stem];old=findall(groot,'Type','figure','Tag',tag);
   if isempty(old),f0=openfig(dest,'new','visible');set(f0,'Tag',tag,'WindowStyle','docked');else,figure(old(1));end
  end
 end
 function G=criticalGeometry(E)
  P=E.e.optimizer.Set;vertices={};faces={};values={};offset=0;
  for k=1:numel(P)
   V=P(k).V;if size(V,1)<3,continue;end
   h=convhull(V(:,1),V(:,2));V=V(h(1:end-1),:);aff=P(k).Functions('primal');
   assert(size(aff.F,2)==2,'Control-law parameter dimension differs from plotted states.');
   U=(aff.F(1:cfg.nu,:)*V'+aff.g(1:cfg.nu))';
   vertices{end+1}=V.*E.teacher.scale(:)';values{end+1}=U;faces{end+1}=offset+(1:size(V,1));offset=offset+size(V,1); %#ok<AGROW>
  end
  assert(~isempty(vertices),'No full-dimensional critical regions.');
  V=vertcat(vertices{:});U=vertcat(values{:});F=nan(numel(faces),max(cellfun(@numel,faces)));for k=1:numel(faces),F(k,1:numel(faces{k}))=faces{k};end
  addpath(fullfile(codeDir,'generated'),'-begin');query=str2func(E.teacher.functionName);maxDifference=0;
  for k=unique(round(linspace(1,numel(faces),min(8,numel(faces)))))
   rows=faces{k};[u,region]=query(mean(V(rows,:),1)');assert(region>0&&all(isfinite(u)));
   maxDifference=max(maxDifference,max(abs(u(:)'-mean(U(rows,:),1))));
  end
  assert(maxDifference<1e-5,'Plotted affine law differs from exported EMPC.');
  fprintf('AFFINE_PLOT_VERIFIED %s R=%g maxDutyDifference=%.3g\n',cfg.id,E.teacher.Rload,maxDifference);
  G=struct('xy',V,'faces',F,'u',U,'regionCount',numel(P));
 end
 function f=newFigure(name,width,height)
  f=figure('Visible','off','Name',[cfg.id ' | ' name],'NumberTitle','off','Color','w','Position',[80 80 width height],...
   'DefaultAxesFontName','Times New Roman','DefaultAxesFontSize',11,'DefaultTextFontName','Times New Roman','DefaultLineLineWidth',1.1,'DefaultAxesColorOrder',palette);
  colormap(f,parula(256));
 end
 function decorate(),grid on;box on;set(gca,'TickDir','out','LineWidth',.8,'GridAlpha',.12,'Layer','top');end
 function finish(f,stem,deps) %#ok<INUSD>
  tag=[cfg.id '_' stem];old=findall(groot,'Type','figure','Tag',tag);if ~isempty(old),close(old);end
  set(f,'Tag',tag);drawnow;savefig(f,fullfile(outDir,[stem '.fig']));
  exportgraphics(f,fullfile(outDir,[stem '.png']),'Resolution',450);
  tpc_export_figure_pdf(f,fullfile(outDir,[stem '.pdf']));
  savefig(f,fullfile(outDir,[stem '.fig']));
  if desktop,set(f,'WindowStyle','docked','Visible','on');drawnow;else,close(f);end
 end
end
function rows=thin(rows,n),if numel(rows)>n,rows=rows(unique(round(linspace(1,numel(rows),n))));end;end
function value=unit(channel),value='A';if channel==2,value='V';end;end
function rows=envelopeRows(a,bins)
% Retain actual min/max samples in each bin, including narrow excursions.
n=size(a,1);edges=unique(round(linspace(1,n+1,min(bins,n)+1)));channels=size(a,2);
rows=zeros(2+2*channels*(numel(edges)-1),1);rows(1:2)=[1;n];used=2;
for k=1:numel(edges)-1
 first=edges(k);last=edges(k+1)-1;[~,lo]=min(a(first:last,:),[],1);[~,hi]=max(a(first:last,:),[],1);
 selected=first-1+[lo(:);hi(:)];rows(used+(1:numel(selected)))=selected;used=used+numel(selected);
end
rows=unique(rows(1:used));
end
